11: 	// Remove caracteres não numéricos (. , / -)
12: 	re := regexp.MustCompile(`\D`)
13: 	cnpj = re.ReplaceAllString(cnpj, "")
14: 
15: 	// CNPJ precisa ter exatamente 14 dígitos numéricos
16: 	if len(cnpj) != 14 {
17: 		return false
18: 	}
19: 
20: 	// Rejeita sequências conhecidas de números repetidos
