28: 			return false
29: 		}
30: 	}
31: 
32: 	// Validação do Primeiro Dígito Verificador
33: 	weightsFirst := []int{5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2}
34: 	sum := 0
35: 	for i := 0; i < 12; i++ {
36: 		num, _ := strconv.Atoi(string(cnpj[i]))
37: 		sum += num * weightsFirst[i]
38: 	}
39: 	remainder := sum % 11
40: 	digit1 := 0
41: 	if remainder >= 2 {
42: 		digit1 = 11 - remainder
43: 	}
44: 	if strconv.Itoa(digit1) != string(cnpj[12]) {
45: 		return false
46: 	}
47: 
48: 	// Validação do Segundo Dígito Verificador
49: 	weightsSecond := []int{6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2}
50: 	sum = 0
51: 	for i := 0; i < 13; i++ {
52: 		num, _ := strconv.Atoi(string(cnpj[i]))
53: 		sum += num * weightsSecond[i]
54: 	}
55: 	remainder = sum % 11
56: 	digit2 := 0
57: 	if remainder >= 2 {
58: 		digit2 = 11 - remainder
59: 	}
