args.CodeContent:
"package main

import (
	"html/template"
	"os"
	"path/filepath"

	"imc-server/internal/models"
)

type GridPageDetail struct {
	Grid      models.WeeklyMasterGrid                 `json:"grid"`
	Schedules map[string]*models.BasicSchedule          `json:"schedules"`
	Configs   map[string]*models.CommercialBlockConfig  `json:"configs"`
}

type GridsPageData struct {
	Title          string
	LoggedUser     string
	ErrorMessage   string
	SuccessMessage string
	Form           map[string]string
	Tenants        []models.Tenant
	Grids          []GridPageDetail
	GridsJSON      template.JS
	User           map[string]string
	Theme          map[string]string
}

func main() {
	theme := map[string]string{
		"LogoURL":              "/static/img/logo-imc.png",
		"PrimaryColor":         "#4364f7",
		"SecondaryColor":       "#161925",
		"BackgroundColor":      "#0f111a",
		"FontColor":            "#ffffff",
		"FieldBackgroundColor": "#161925",
	}

	data := GridsPageData{
		Title:      "Grades de Áudio",
		LoggedUser: "Carlos",
		Tenants:    []models.Tenant{},
		Grids:      []GridPageDetail{},
		GridsJSON:  "[]",
		Form:       make(map[string]string),
		User: map[string]string{
			"Name": "Carlos",
			"Role": "Administrador",
		},
		Theme: theme,
	}

	tmpl, err := template.ParseFiles("web/templates/grids_audio.html")
	if err != nil {
		panic(err)
	}

	outPath := filepath.Join("scratch", "rendered_grids_audio.html")
	f, err := os.Create(outPath)
	if err != nil {
		panic(err)
	}
	defer f.Close()

	err = tmpl.Execute(f, data)
	if err != nil {
		panic(err)
	}
}
"

